//! UMBRA's own vectors: `UMBRA-KEM` (Part 5 rules `CRY-045`, `CRY-046`) and
//! the key hierarchy (`CRY-121`, Part 6 rule `WIR-350`).
//!
//! The files under `tests/vectors/umbra/` are self-generated by this crate,
//! and no independent implementation has confirmed them yet. The ignored
//! test `generate` writes both files; run it after a change to the inputs,
//! then run `scripts/vectors.py`.
#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    clippy::panic
)]

use std::{fs, path::PathBuf};

use serde_json::{json, Value};
use umbra_crypto::{
    hierarchy::RootIdentity,
    kem::{self, Ciphertext, KeyPair, PublicKey},
    secret::Secret,
    Error,
};

fn vectors() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/vectors/umbra")
}

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("hex"))
        .collect()
}

fn arr<const N: usize>(s: &str) -> [u8; N] {
    unhex(s).try_into().expect("length")
}

/// Fixed, published inputs. A vector is only useful when its inputs are
/// stated, thus these are constants and not random.
const X_SK: [u8; 32] = [0x11; 32];
const D: [u8; 32] = [0x22; 32];
const Z: [u8; 32] = [0x33; 32];
const EK_X: [u8; 32] = [0x44; 32];
const M: [u8; 32] = [0x55; 32];
const ROOT: [u8; 32] = [0x66; 32];
const SALT_C: [u8; 16] = [0x77; 16];

fn dz() -> Secret<64> {
    let mut b = [0u8; 64];
    b[..32].copy_from_slice(&D);
    b[32..].copy_from_slice(&Z);
    Secret::new(b)
}

fn keypair_json(kp: &KeyPair) -> Value {
    json!({ "pk": hex(&kp.public().to_bytes()) })
}

fn build() -> (Value, Value) {
    let kp = KeyPair::from_seeds(Secret::new(X_SK), dz());
    let (ct, ss) = kem::encapsulate_deterministic(kp.public(), Secret::new(EK_X), Secret::new(M));
    let mut zero_x = *ct.as_bytes();
    zero_x[..32].fill(0);
    let kem_v = json!({
        "note": "UMBRA-KEM of Part 5 §5.3. Self-generated; not independently confirmed.",
        "x_sk": hex(&X_SK), "d": hex(&D), "z": hex(&Z),
        "pk": hex(&kp.public().to_bytes()),
        "ek_x": hex(&EK_X), "m": hex(&M),
        "ct": hex(ct.as_bytes()),
        "ss": hex(ss.expose()),
        "negative_all_zero_pub_x": { "ct": hex(&zero_x), "result": "reject" },
    });
    let root = RootIdentity::new(Secret::new(ROOT));
    let hier_v = json!({
        "note": "Key hierarchy of Part 5 §5.2 from one RootIdentity. Self-generated; not independently confirmed.",
        "root_identity": hex(&ROOT),
        "k_rng_harden": hex(root.rng_harden_key().expose()),
        "k_store": hex(root.storage_key().expose()),
        "k_devset": hex(root.device_set_key().expose()),
        "pairwise": { "salt_c": hex(&SALT_C), "key": keypair_json(&root.pairwise_identity(&SALT_C)) },
        "public_address": [
            { "j": 0, "key": keypair_json(&root.public_address_key(0)) },
            { "j": 1, "key": keypair_json(&root.public_address_key(1)) },
        ],
        "handle_key": [
            { "j": 0, "r": 0, "key": keypair_json(&root.handle_key(0, 0)) },
            { "j": 0, "r": 1, "key": keypair_json(&root.handle_key(0, 1)) },
        ],
    });
    (kem_v, hier_v)
}

#[test]
#[ignore = "writes the vector files; run by hand"]
fn generate() {
    let (kem_v, hier_v) = build();
    fs::create_dir_all(vectors()).unwrap();
    fs::write(
        vectors().join("kem.json"),
        serde_json::to_string_pretty(&kem_v).unwrap(),
    )
    .unwrap();
    fs::write(
        vectors().join("hierarchy.json"),
        serde_json::to_string_pretty(&hier_v).unwrap(),
    )
    .unwrap();
}

fn load(name: &str) -> Value {
    let path = vectors().join(name);
    serde_json::from_str(
        &fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display())),
    )
    .expect("json")
}

#[test]
fn kem_vector_holds() {
    let v = load("kem.json");
    let kp = KeyPair::from_seeds(Secret::new(arr(v["x_sk"].as_str().unwrap())), {
        let mut b = [0u8; 64];
        b[..32].copy_from_slice(&unhex(v["d"].as_str().unwrap()));
        b[32..].copy_from_slice(&unhex(v["z"].as_str().unwrap()));
        Secret::new(b)
    });
    assert_eq!(hex(&kp.public().to_bytes()), v["pk"]);
    let pk = PublicKey::from_bytes(&unhex(v["pk"].as_str().unwrap())).unwrap();
    let (ct, ss) = kem::encapsulate_deterministic(
        &pk,
        Secret::new(arr(v["ek_x"].as_str().unwrap())),
        Secret::new(arr(v["m"].as_str().unwrap())),
    );
    assert_eq!(hex(ct.as_bytes()), v["ct"]);
    assert_eq!(hex(ss.expose()), v["ss"]);
    // CRY-044: Encap and Decap agree for one (pk, sk) pair and one ct.
    assert_eq!(hex(kp.decapsulate(&ct).unwrap().expose()), v["ss"]);
    // CRY-046: the all-zero pub_X negative case.
    let bad = Ciphertext::from_bytes(&unhex(v["negative_all_zero_pub_x"]["ct"].as_str().unwrap()))
        .unwrap();
    assert_eq!(kp.decapsulate(&bad).err(), Some(Error::Kem));
}

#[test]
fn hierarchy_vector_holds() {
    let (_, fresh) = build();
    let v = load("hierarchy.json");
    assert_eq!(v, fresh);
}
